import{_ as o,o as t,c as i,ag as a}from"./chunks/framework.DXGyWiRo.js";const h=JSON.parse('{"title":"Security","description":"Security practices and implementation details for DOAI Proxy","frontmatter":{"title":"Security","description":"Security practices and implementation details for DOAI Proxy"},"headers":[],"relativePath":"guides/security.md","filePath":"guides/security.md"}'),r={name:"guides/security.md"};function n(s,e,d,c,l,u){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h1><p>DOAI Proxy takes security seriously — even if the name doesn&#39;t.</p><h2 id="for-users" tabindex="-1">For Users <a class="header-anchor" href="#for-users" aria-label="Permalink to &quot;For Users&quot;">​</a></h2><ol><li><strong>Never commit <code>.env</code></strong> to version control</li><li><strong>Use strong API keys</strong> — Obtain from official sources</li><li><strong>Keep API keys secret</strong> — Never share or commit</li><li><strong>Use HTTPS in production</strong> — Add a reverse proxy with SSL</li><li><strong>Add authentication</strong> — Use <code>AUTH_MODE=required</code> for production (see <a href="/guides/authentication">Authentication</a>)</li><li><strong>Monitor logs</strong> — Regularly check for suspicious activity</li></ol><h2 id="for-repository-maintainers" tabindex="-1">For Repository Maintainers <a class="header-anchor" href="#for-repository-maintainers" aria-label="Permalink to &quot;For Repository Maintainers&quot;">​</a></h2><ol><li><strong>No secrets in code</strong> — All secrets loaded from environment variables</li><li><strong>No sensitive files tracked</strong> — <code>.env</code>, <code>*.log</code>, and sensitive files in <code>.gitignore</code></li><li><strong>Regular dependency audits</strong> — Run <code>npm audit fix</code> regularly</li><li><strong>Keep dependencies updated</strong> — Use <code>npm update</code> for security patches</li></ol><h2 id="implementation-details" tabindex="-1">Implementation Details <a class="header-anchor" href="#implementation-details" aria-label="Permalink to &quot;Implementation Details&quot;">​</a></h2><h3 id="timing-safe-auth-comparison" tabindex="-1">Timing-Safe Auth Comparison <a class="header-anchor" href="#timing-safe-auth-comparison" aria-label="Permalink to &quot;Timing-Safe Auth Comparison&quot;">​</a></h3><p>All API key checks use <code>crypto.timingSafeEqual</code> to prevent timing attacks.</p><h3 id="log-sanitization" tabindex="-1">Log Sanitization <a class="header-anchor" href="#log-sanitization" aria-label="Permalink to &quot;Log Sanitization&quot;">​</a></h3><p>Authorization headers are redacted to <code>[REDACTED]</code>. Response bodies with <code>content</code> &gt; 200 chars are truncated. Keys containing <code>password</code>, <code>token</code>, <code>api_key</code> are replaced with <code>[REDACTED]</code>.</p><h3 id="trust-proxy" tabindex="-1">Trust Proxy <a class="header-anchor" href="#trust-proxy" aria-label="Permalink to &quot;Trust Proxy&quot;">​</a></h3><p><code>trust proxy</code> is enabled only in <code>external</code> auth mode.</p><h3 id="body-size-limit" tabindex="-1">Body Size Limit <a class="header-anchor" href="#body-size-limit" aria-label="Permalink to &quot;Body Size Limit&quot;">​</a></h3><p>JSON body limit: 50 MB.</p><h2 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h2><ul><li><strong>Proxy does not execute tools</strong> — Tool calls are formatted but not executed</li><li><strong>No rate limiting</strong> — Consider adding for production deployments</li><li><strong>No authentication by default</strong> — Configure <code>AUTH_MODE</code> explicitly</li><li><strong>Logs stored locally</strong> — Logs are written to disk and not encrypted</li></ul><h2 id="secrets-management" tabindex="-1">Secrets Management <a class="header-anchor" href="#secrets-management" aria-label="Permalink to &quot;Secrets Management&quot;">​</a></h2><p>Secrets live in <code>.env</code> file (not committed). <code>STRAICO_API_KEY</code> and <code>PROXY_API_KEY</code> are consumed from environment. No vault or rotation mechanism.</p>',19)])])}const p=o(r,[["render",n]]);export{h as __pageData,p as default};
